import { writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { categories, dishes, affinities, brands } from '../worker/src/bot/food-knowledge.js';

const quote = value => `'${String(value).replaceAll("'", "''")}'`;
const row = (table, columns, values) => `INSERT OR IGNORE INTO ${table} (${columns.join(', ')}) VALUES (${values.map(quote).join(', ')});`;
const sql = [
  '-- Generated by scripts/build-food-knowledge-seed.mjs. Existing D1 edits are preserved.',
  ...categories.map(item => row('food_categories',['id','label_vi','aliases','query_en','query_zh'],[item.id,item.vi,JSON.stringify(item.aliases),JSON.stringify(item.en),JSON.stringify(item.zh)])),
  ...dishes.map(item => row('food_dishes',['id','category_id','label_vi','aliases','query_en','query_zh'],[item.id,item.category,item.vi,JSON.stringify(item.aliases),item.en,item.zh])),
  ...affinities.map(([dish,category,confidence]) => row('food_affinities',['dish_id','category_id','confidence'],[dish,category,confidence])),
  ...brands.map(item => row('venue_brands',['id','name','category_id','aliases','countries'],[item.id,item.name,item.category,JSON.stringify(item.aliases),JSON.stringify(item.countries)])),
  ''
].join('\n');
await writeFile(fileURLToPath(new URL('../worker/food-knowledge-seed.sql',import.meta.url)),sql);
